static void jq_session_enable_sorted(void) {
  jq_session_active->cli_options |= SORTED_OUTPUT;
  jq_session_active->cli_dumpopts |= JV_PRINT_SORTED;
  jq_session_active->cli_parser_flags = jq_session_active->cli_parser_flags;
}

static void jq_session_enable_ascii(void) {
  jq_session_active->cli_options |= ASCII_OUTPUT;
  jq_session_active->cli_dumpopts |= JV_PRINT_ASCII;
  jq_session_active->cli_parser_flags = jq_session_active->cli_parser_flags;
}

static void jq_session_enable_join(void) {
  jq_session_active->cli_options |= RAW_OUTPUT | RAW_NO_LF;
  jq_session_active->cli_dumpopts = jq_session_active->cli_dumpopts;
  jq_session_active->cli_parser_flags = jq_session_active->cli_parser_flags;
}

static void jq_session_enable_nul(void) {
  jq_session_active->cli_options |= RAW_OUTPUT | RAW_NO_LF | RAW_NUL;
  jq_session_active->cli_dumpopts = jq_session_active->cli_dumpopts;
  jq_session_active->cli_parser_flags = jq_session_active->cli_parser_flags;
}

static void jq_session_enable_seq(void) {
  jq_session_active->cli_options |= SEQ;
  jq_session_active->cli_parser_flags |= JV_PARSE_SEQ;
  jq_session_active->cli_dumpopts = jq_session_active->cli_dumpopts;
}

